import axios from 'axios';
import { ImageGenConfig } from '../types';

export class ImageGenService {
  private config: ImageGenConfig;

  constructor(config: ImageGenConfig) {
    this.config = config;
  }

  async generateImage(prompt: string): Promise<string> {
    try {
      console.log('Generating image with prompt:', prompt);

      if (this.config.provider === 'gemini') {
        return await this.generateWithGemini(prompt);
      } else if (this.config.provider === 'vllm') {
        return await this.generateWithVLLM(prompt);
      } else {
        throw new Error(`Unsupported image generation provider: ${this.config.provider}`);
      }
    } catch (error) {
      console.error('Image generation error:', error);
      throw new Error('Failed to generate image');
    }
  }

  private async generateWithGemini(prompt: string): Promise<string> {
    if (!this.config.apiKey) {
      throw new Error('Gemini API key not configured for image generation');
    }

    console.log('Sending image generation request to Gemini Imagen...');

    try {
      // Use Gemini's Imagen API
      const response = await axios.post(
        `https://generativelanguage.googleapis.com/v1beta/models/imagen-3.0-generate-001:generateImage?key=${this.config.apiKey}`,
        {
          prompt: {
            text: prompt
          },
          safetySettings: [
            {
              category: "HARM_CATEGORY_SEXUALLY_EXPLICIT",
              threshold: "BLOCK_LOW_AND_ABOVE"
            },
            {
              category: "HARM_CATEGORY_HATE_SPEECH", 
              threshold: "BLOCK_LOW_AND_ABOVE"
            },
            {
              category: "HARM_CATEGORY_HARASSMENT",
              threshold: "BLOCK_LOW_AND_ABOVE"
            },
            {
              category: "HARM_CATEGORY_DANGEROUS_CONTENT",
              threshold: "BLOCK_LOW_AND_ABOVE"
            }
          ],
          generationConfig: {
            aspectRatio: this.config.width && this.config.height 
              ? this.config.width === this.config.height ? "SQUARE" : "LANDSCAPE"
              : "SQUARE",
            negativePrompt: "blurry, low quality, distorted, ugly, watermark",
            includeRaiInfo: false
          }
        },
        {
          headers: {
            'Content-Type': 'application/json',
          },
          timeout: 60000 // 60 second timeout
        }
      );

      console.log('Gemini Imagen response:', response.data);

      if (!response.data.candidates || response.data.candidates.length === 0) {
        throw new Error('No image generated by Gemini Imagen');
      }

      const candidate = response.data.candidates[0];
      if (candidate.finishReason !== 'STOP') {
        throw new Error(`Image generation failed: ${candidate.finishReason}`);
      }

      // Return the base64 image data
      const imageData = candidate.image.imageBytes;
      return `data:image/png;base64,${imageData}`;

    } catch (error) {
      if (axios.isAxiosError(error)) {
        console.error('Gemini Imagen API error:', error.response?.data || error.message);
        const errorMessage = error.response?.data?.error?.message || error.message;
        throw new Error(`Gemini Imagen API error: ${errorMessage}`);
      }
      throw error;
    }
  }

  private async generateWithVLLM(prompt: string): Promise<string> {
    if (!this.config.baseUrl) {
      throw new Error('vLLM base URL not configured for image generation');
    }

    // Prepare the request for vLLM image generation
    const requestBody = {
      model: this.config.model || 'flux-1-schnell',
      prompt: prompt,
      steps: this.config.steps || 20,
      width: this.config.width || 512,
      height: this.config.height || 512,
      guidance_scale: 7.5,
      negative_prompt: "blurry, low quality, distorted, ugly"
    };

    console.log('Sending image generation request to vLLM:', requestBody);

    try {
      const response = await axios.post(
        `${this.config.baseUrl}/v1/images/generations`,
        requestBody,
        {
          headers: {
            'Content-Type': 'application/json',
          },
          timeout: 60000 // 60 second timeout for image generation
        }
      );

      if (!response.data.data || response.data.data.length === 0) {
        throw new Error('No image data returned from vLLM server');
      }

      // Return the base64 image or URL
      const imageData = response.data.data[0];
      if (imageData.b64_json) {
        return `data:image/png;base64,${imageData.b64_json}`;
      } else if (imageData.url) {
        return imageData.url;
      } else {
        throw new Error('No image URL or base64 data in response');
      }
    } catch (error) {
      if (axios.isAxiosError(error)) {
        console.error('vLLM API error:', error.response?.data || error.message);
        throw new Error(`vLLM API error: ${error.response?.data?.error?.message || error.message}`);
      }
      throw error;
    }
  }

  updateConfig(newConfig: Partial<ImageGenConfig>) {
    this.config = { ...this.config, ...newConfig };
  }

  getConfig(): ImageGenConfig {
    return { ...this.config };
  }
}

// Default image generation configuration
export const defaultImageGenConfig = {
  provider: 'vllm' as const,
  baseUrl: process.env.REACT_APP_VLLM_IMAGE_BASE_URL || 'http://localhost:8001',
  model: 'flux-1-schnell',
  steps: 20,
  width: 512,
  height: 512
};
